{
  "assessment": "Austria faces a mild economic contraction (-1.2% growth) with moderate inflation and low military spending. As a stable European Union member, our immediate priority is to stimulate economic recovery through targeted infrastructure investment and slight monetary easing while maintaining strong diplomatic ties within the EU.",
  "directives": [
    {
      "type": "set_spending",
      "target": null,
      "amount": 4.5,
      "sub": "infrastructure",
      "order": "Increase infrastructure spending to 4.5% of GDP to stimulate economic growth."
    },
    {
      "type": "monetary_policy",
      "target": null,
      "amount": -0.25,
      "sub": "",
      "order": "Encourage easier monetary conditions by lowering the policy rate slightly."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 1.2,
      "sub": "military",
      "order": "Increase military spending to 1.2% of GDP to ensure adequate national defense readiness."
    }
  ],
  "cables": [
    {
      "to": "DEU",
      "private": true,
      "text": "Greetings from Vienna. We look forward to continuing our close economic and diplomatic partnership with Germany."
    },
    {
      "to": "ITA",
      "private": true,
      "text": "Reaffirming our mutual commitment to European stability and robust cross-border trade."
    }
  ],
  "public_statement": "The Austrian government is launching a comprehensive economic revitalization plan focused on modernizing our national infrastructure, supporting workers, and fostering sustainable growth across all regions.",
  "standing_orders": [
    {
      "when": "growth_below:0.0",
      "do": {
        "type": "invest_infrastructure",
        "target": null,
        "amount": 0.5,
        "sub": "",
        "order": "Deploy additional infrastructure investment when economic growth dips below zero."
      }
    }
  ],
  "detailed_report": "economy"
}
